:root {
  --color-bg: #fffafb;
  --color-surface: #fbeef2;
  --color-text: #2b2b2b;
  --color-text-muted: #5a4a4f;
  --color-primary-dark: #7a2e49;
  --color-primary-darker: #5c2238;
  --color-accent-on-dark: #f3d6e2;
  --color-dark-bg: #3a1626;
  --color-border: #e3b9c7;
  --color-white: #ffffff;
  --font-body: Georgia, "Times New Roman", serif;
  --font-heading: "Palatino Linotype", "Book Antiqua", Georgia, serif;
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 1.5rem;
  --space-lg: 2.5rem;
  --space-xl: 4rem;
  --radius: 0.5rem;
  --max-width: 75rem;
}

*, *::before, *::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--font-body);
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  font-size: 1rem;
}

h1, h2, h3 {
  font-family: var(--font-heading);
  color: var(--color-primary-darker);
  line-height: 1.25;
  margin-top: 0;
}

p { margin-top: 0; }

a {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

a:hover { color: var(--color-primary-darker); }

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible {
  outline: 3px solid var(--color-primary-darker);
  outline-offset: 2px;
}

img { max-width: 100%; height: auto; display: block; }

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.25rem;
}

/* Header */
header {
  background-color: var(--color-white);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-sm);
  padding-top: var(--space-sm);
  padding-bottom: var(--space-sm);
}

.logo {
  font-family: "Palatino Linotype", "Book Antiqua", serif;
  font-variant: small-caps;
  font-weight: 400;
  letter-spacing: 0.25em;
  font-size: clamp(1.1rem, 4vw, 1.5rem);
  color: var(--color-primary-dark);
  text-decoration: none;
  border-bottom: 1px solid var(--color-primary-dark);
  width: fit-content;
  padding-bottom: 0.15em;
}

.logo:hover { color: var(--color-primary-darker); }

nav ul.nav-list {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
  margin: 0;
  padding: 0;
}

nav ul.nav-list a {
  text-decoration: none;
  color: var(--color-text);
  font-size: 0.95rem;
  padding: 0.4rem 0.2rem;
}

nav ul.nav-list a:hover {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

/* Footer */
footer {
  background-color: var(--color-dark-bg);
  color: var(--color-accent-on-dark);
  padding: var(--space-lg) 0;
  margin-top: var(--space-xl);
}

.footer-inner p { margin: 0.25rem 0; }

.footer-brand {
  font-family: var(--font-heading);
  font-variant: small-caps;
  letter-spacing: 0.15em;
  font-size: 1.2rem;
  color: var(--color-accent-on-dark);
}

footer a { color: var(--color-accent-on-dark); }

.copyright {
  margin-top: var(--space-sm);
  font-size: 0.85rem;
  opacity: 0.85;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-family: var(--font-body);
  background-color: var(--color-primary-dark);
  color: var(--color-white);
  border: none;
  border-radius: var(--radius);
  text-decoration: none;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

.btn:hover, .btn:focus-visible {
  background-color: var(--color-primary-darker);
  color: var(--color-white);
}

.btn-secondary {
  background-color: transparent;
  color: var(--color-primary-dark);
  border: 2px solid var(--color-primary-dark);
}

.btn-secondary:hover {
  background-color: var(--color-primary-dark);
  color: var(--color-white);
}

/* Cards */
.card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--space-md);
}

.card h3 { margin-bottom: 0.5rem; }

/* Grid helper */
.grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
}

/* Sections */
section {
  padding: var(--space-xl) 0;
}

section.alt-bg {
  background-color: var(--color-surface);
}

section.dark-bg {
  background-color: var(--color-dark-bg);
  color: var(--color-accent-on-dark);
}

section.dark-bg h2, section.dark-bg h3 {
  color: var(--color-accent-on-dark);
}

/* Forms */
form {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  max-width: 40rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

label {
  font-weight: bold;
  color: var(--color-text);
}

input, select, textarea {
  min-height: 44px;
  padding: 0.6rem 0.75rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  font-family: var(--font-body);
  font-size: 1rem;
  background-color: var(--color-white);
  color: var(--color-text);
}

textarea { min-height: 7rem; resize: vertical; }

input:focus, select:focus, textarea:focus {
  border-color: var(--color-primary-dark);
}

/* Mobile breakpoint */
@media (max-width: 600px) {
  .header-inner { flex-direction: column; align-items: flex-start; }
  nav ul.nav-list { flex-direction: column; gap: 0.25rem; width: 100%; }
  section { padding: var(--space-lg) 0; }
  .grid { grid-template-columns: 1fr; }
}

/* Desktop breakpoint */
@media (min-width: 601px) {
  .grid-2 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(3, 1fr); }
  form { max-width: 32rem; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  * { animation: none !important; transition: none !important; }
}

