.index-hero {
  background-color: var(--color-surface);
  padding: var(--space-xl) 0;
}

.index-hero-inner {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  max-width: 45rem;
}

.index-hero-text {
  color: var(--color-text-muted);
  font-size: 1.1rem;
}

.index-testimonial {
  margin: 0;
  font-style: italic;
}

.index-testimonial footer {
  margin-top: var(--space-sm);
  font-style: normal;
  font-weight: bold;
  color: var(--color-primary-dark);
}

.index-hours-list {
  list-style: none;
  padding: 0;
  margin: 0 0 var(--space-md) 0;
}

.index-hours-list li {
  padding: 0.25rem 0;
  border-bottom: 1px solid rgba(243, 214, 226, 0.3);
}

.index-map {
  border-radius: var(--radius);
  width: 100%;
  border: 1px solid var(--color-border);
}

@media (max-width: 600px) {
  .index-hero-inner { max-width: 100%; }
  .index-hero { padding: var(--space-lg) 0; }
}

@media (min-width: 601px) {
  .index-hero-inner { max-width: 45rem; }
}

